                $availablePoints = (float)$userData['availableArabianPoints'];
                $endBalance = $availablePoints + $refundAmount;

               

                // Insert load balance
                $refundData["load_balance_id"]		 =	(int)$this->common_model->getNextSequence('uw_loadBalance');
